import{_ as t,o as e,c as a,ae as n}from"./chunks/framework.Dzr56EFm.js";const c=JSON.parse('{"title":"设计趋势 - 2026-07-08","description":"","frontmatter":{"date":"2026-07-08T00:00:00.000Z","category":"UX Trend"},"headers":[],"relativePath":"daily/2026-07-08-uxtrend.md","filePath":"daily/2026-07-08-uxtrend.md"}'),o={name:"daily/2026-07-08-uxtrend.md"};function s(i,r,g,p,h,l){return e(),a("div",null,[...r[0]||(r[0]=[n('<h1 id="设计趋势-2026-07-08" tabindex="-1">设计趋势 - 2026-07-08 <a class="header-anchor" href="#设计趋势-2026-07-08" aria-label="Permalink to &quot;设计趋势 - 2026-07-08&quot;">​</a></h1><blockquote><p>AI交互方式、Prompt UX、Agent UX、Workflow</p></blockquote><h2 id="今日概览" tabindex="-1">今日概览 <a class="header-anchor" href="#今日概览" aria-label="Permalink to &quot;今日概览&quot;">​</a></h2><p>今日设计趋势聚焦于AI与用户体验的融合。主要动态包括：1) 面向代理的用户体验设计，推动数字设备新体验；2) Cursor AI集成代码编辑器，革新交互方式；3) AI技术优化设计流程，提升效率；4) 探讨AI代理工作流设计模式；5) 设计代理系统需遵循7原则，增强信任与智能。最值得关注的是Cursor AI的集成应用和AI代理工作流设计模式的探讨。</p><hr><h3 id="_1-面向代理的用户体验设计" tabindex="-1">1. 面向代理的用户体验设计 <a class="header-anchor" href="#_1-面向代理的用户体验设计" aria-label="Permalink to &quot;1. 面向代理的用户体验设计&quot;">​</a></h3><p><strong>原文标题</strong>: <a href="https://medium.com/microsoft-design/ux-design-for-agents-11336728b445" target="_blank" rel="noreferrer">UX design for agents</a></p><p><strong>一句话摘要</strong>: 设计原则助力数字设备新用户体验</p><p><strong>能解决什么问题</strong>: 传统UX原则无法完全应对AI驱动代理系统的独特挑战</p><p><strong>产品应用</strong>: 可应用于产品设计，以人为中心，加速开发代理系统</p><p><strong>示例场景</strong>: AI代理辅助团队协作，提升工作效率</p><hr><h3 id="_2-光标、氛围编码和手稿-ai所需的用户体验革命" tabindex="-1">2. 光标、氛围编码和手稿：AI所需的用户体验革命 <a class="header-anchor" href="#_2-光标、氛围编码和手稿-ai所需的用户体验革命" aria-label="Permalink to &quot;2. 光标、氛围编码和手稿：AI所需的用户体验革命&quot;">​</a></h3><p><strong>原文标题</strong>: <a href="https://uxdesign.cc/cursor-vibe-coding-and-manus-the-ux-revolution-that-ai-needs-3d3a0f8ccdfa" target="_blank" rel="noreferrer">Cursor, “vibe coding,” and Manus: the UX revolution that AI needs | by Amy Chivavibul | UX Collective</a></p><p><strong>一句话摘要</strong>: Cursor将AI集成到代码编辑器中，实现更自然的交互。</p><p><strong>能解决什么问题</strong>: 解决传统编程工具与AI协作效率低下的问题。</p><p><strong>产品应用</strong>: 适用于软件开发，提高代码编写、测试和修复的效率。</p><p><strong>示例场景</strong>: 开发者通过Cursor直接与AI对话，优化代码性能。</p><hr><h3 id="_3-ai如何改变我的设计工作流程" tabindex="-1">3. AI如何改变我的设计工作流程 <a class="header-anchor" href="#_3-ai如何改变我的设计工作流程" aria-label="Permalink to &quot;3. AI如何改变我的设计工作流程&quot;">​</a></h3><p><strong>原文标题</strong>: <a href="https://medium.com/@kazdenc/how-my-design-workflow-is-changing-with-ai-bc80e7fa3323" target="_blank" rel="noreferrer">How my design workflow is changing with AI</a></p><p><strong>一句话摘要</strong>: AI技术使设计流程更快速、协作且高效。</p><p><strong>能解决什么问题</strong>: 提高设计效率，减少从概念到原型的时间。</p><p><strong>产品应用</strong>: 适用于产品设计，通过AI工具加速原型迭代。</p><p><strong>示例场景</strong>: 设计师使用Figma和Cursor快速迭代原型。</p><hr><h3 id="_4-ai代理工作流设计模式概览" tabindex="-1">4. AI代理工作流设计模式概览 <a class="header-anchor" href="#_4-ai代理工作流设计模式概览" aria-label="Permalink to &quot;4. AI代理工作流设计模式概览&quot;">​</a></h3><p><strong>原文标题</strong>: <a href="https://medium.com/binome/ai-agent-workflow-design-patterns-an-overview-cf9e1f609696" target="_blank" rel="noreferrer">AI Agent Workflow Design Patterns — An Overview | by Craig Li, Ph.D</a></p><p><strong>一句话摘要</strong>: 探讨AI代理工作流设计模式，强调工作流作为任务协调器的作用。</p><p><strong>能解决什么问题</strong>: 如何设计AI代理以模拟人类推理、规划和执行任务。</p><p><strong>产品应用</strong>: 可应用于开发智能代理产品，通过工作流模式灵活处理不同问题。</p><p><strong>示例场景</strong>: 智能客服系统通过工作流模式处理客户咨询。</p><hr><h3 id="_5-代理式用户体验-设计代理系统的7个原则" tabindex="-1">5. 代理式用户体验：设计代理系统的7个原则 <a class="header-anchor" href="#_5-代理式用户体验-设计代理系统的7个原则" aria-label="Permalink to &quot;5. 代理式用户体验：设计代理系统的7个原则&quot;">​</a></h3><p><strong>原文标题</strong>: <a href="https://medium.com/design-bootcamp/agentic-ux-7-principles-for-designing-systems-with-agents-019512c2caa9" target="_blank" rel="noreferrer">Agentic UX: 7 principles for designing systems with agents</a></p><p><strong>一句话摘要</strong>: 设计代理系统时需考虑上下文双向流动，以增强信任感和智能行为。</p><p><strong>能解决什么问题</strong>: 解决代理系统在用户体验中的上下文断裂和信任问题。</p><p><strong>产品应用</strong>: 适用于需要智能代理辅助的任何产品，如客服、自动化办公等。</p><p><strong>示例场景</strong>: 智能助手在用户工作流程中自动完成数据整理和优先级排序。</p><hr><h3 id="_6-ai交互模式-让用户识别并互动ai驱动功能" tabindex="-1">6. AI交互模式：让用户识别并互动AI驱动功能 <a class="header-anchor" href="#_6-ai交互模式-让用户识别并互动ai驱动功能" aria-label="Permalink to &quot;6. AI交互模式：让用户识别并互动AI驱动功能&quot;">​</a></h3><p><strong>原文标题</strong>: <a href="https://medium.com/@flik185/ai-interaction-patterns-giving-users-ways-to-recognize-and-interact-with-ai-driven-features-22055a91206b" target="_blank" rel="noreferrer">AI Interaction Patterns: Giving Users Ways to Recognize and Interact With Ai-Driven Features</a></p><p><strong>一句话摘要</strong>: 通过交互模式建立人与AI的信任关系</p><p><strong>能解决什么问题</strong>: 如何让用户轻松识别并有效互动AI功能</p><p><strong>产品应用</strong>: 适用于AI工具，如聊天机器人、分析仪表板等</p><p><strong>示例场景</strong>: 聊天机器人提供问题提示和操作指导</p><hr><h3 id="_7-ai-ux设计模式-人工智能带来新的交互体验" tabindex="-1">7. AI UX设计模式：人工智能带来新的交互体验 <a class="header-anchor" href="#_7-ai-ux设计模式-人工智能带来新的交互体验" aria-label="Permalink to &quot;7. AI UX设计模式：人工智能带来新的交互体验&quot;">​</a></h3><p><strong>原文标题</strong>: <a href="https://lukelance.medium.com/ai-ux-design-patterns-53d9e378f808" target="_blank" rel="noreferrer">AI UX Design Patterns. Artificial Intelligence brings a new… | by Luke Bennis | Medium</a></p><p><strong>一句话摘要</strong>: 介绍AI用户体验设计的关键交互模式</p><p><strong>能解决什么问题</strong>: 帮助设计师规划包含AI的产品时做出更好的UX决策</p><p><strong>产品应用</strong>: 可以应用到实际产品中，通过评估选择最适合的模式</p><p><strong>示例场景</strong>: 使用AI设计模式优化智能助手的用户交互</p><hr><h3 id="_8-在cursor中使用ai可读设计系统进行设计" tabindex="-1">8. 在Cursor中使用AI可读设计系统进行设计 <a class="header-anchor" href="#_8-在cursor中使用ai可读设计系统进行设计" aria-label="Permalink to &quot;8. 在Cursor中使用AI可读设计系统进行设计&quot;">​</a></h3><p><strong>原文标题</strong>: <a href="https://medium.com/design-bootcamp/working-with-ai-readable-design-systems-in-cursor-2bba9c9c09d9" target="_blank" rel="noreferrer">Designing with AI-readable design systems in Cursor</a></p><p><strong>一句话摘要</strong>: AI直接将产品需求和UX规范转化为完整产品流程。</p><p><strong>能解决什么问题</strong>: 解决传统设计流程中效率低下和一致性差的问题。</p><p><strong>产品应用</strong>: 适用于任何需要快速、一致性高的设计原型的产品开发。</p><p><strong>示例场景</strong>: 设计师使用产品需求生成符合设计系统的原型。</p><hr><h3 id="_9-ai在设计中的应用-改变我们的创造方式" tabindex="-1">9. AI在设计中的应用：改变我们的创造方式 <a class="header-anchor" href="#_9-ai在设计中的应用-改变我们的创造方式" aria-label="Permalink to &quot;9. AI在设计中的应用：改变我们的创造方式&quot;">​</a></h3><p><strong>原文标题</strong>: <a href="https://www.figma.com/resource-library/ai-in-design" target="_blank" rel="noreferrer">AI in Design: Transforming the Way We Create | Figma</a></p><p><strong>一句话摘要</strong>: AI正在改变设计工作流程，提高创造力和团队协作。</p><p><strong>能解决什么问题</strong>: AI技术帮助设计师自动化任务，释放时间进行创造性决策。</p><p><strong>产品应用</strong>: 可以应用到产品设计、UI/UX设计等领域，通过AI生成设计选项和优化布局。</p><p><strong>示例场景</strong>: 设计师使用AI生成多个界面布局，快速选择并迭代。</p><hr><h3 id="_10-为代理式用户体验设计指南" tabindex="-1">10. 为代理式用户体验设计指南 <a class="header-anchor" href="#_10-为代理式用户体验设计指南" aria-label="Permalink to &quot;10. 为代理式用户体验设计指南&quot;">​</a></h3><p><strong>原文标题</strong>: <a href="https://medium.com/ai-ux-designers/era-of-agentive-ux-not-agentic-64dd765a0372" target="_blank" rel="noreferrer">Designing for Agentive UX — A Guide</a></p><p><strong>一句话摘要</strong>: 设计代理式用户体验，预测并满足用户未知需求。</p><p><strong>能解决什么问题</strong>: 解决用户寻找未知潜在需求和兴趣的问题。</p><p><strong>产品应用</strong>: 可应用于个性化推荐系统，通过算法分析用户行为和偏好。</p><p><strong>示例场景</strong>: 智能助手根据用户习惯自动推荐新闻和文章。</p><hr>',75)])])}const u=t(o,[["render",s]]);export{c as __pageData,u as default};
